#!/usr/bin/env node
'use strict';
// Read-only HTTPS GET of stylesheet URLs already in the parent-approved HTML.
// Writes only customer evidence, never production or the parent's snapshot/source.
const C=require('./customer-workbench-core-20261114.cjs'),https=require('node:https');
const {fs,path,assert,BASE,ROOT,EXPECTED_HTML,read,sha}=C;
function get(url){return new Promise((resolve,reject)=>{const req=https.get(url,{headers:{'Accept':'text/css','Accept-Encoding':'identity','User-Agent':'CustomerSourceBoundCssEvidence/20261114'}},res=>{if(res.statusCode!==200){res.resume();reject(Error('stylesheet GET '+res.statusCode+' '+url));return;}assert(/(?:text\/css|text\/plain|application\/octet-stream)/.test(res.headers['content-type']??''),'unexpected stylesheet content-type');let size=0,parts=[];res.on('data',d=>{size+=d.length;if(size>5000000){req.destroy(Error('CSS too large'));return;}parts.push(d);});res.on('end',()=>resolve({bytes:Buffer.concat(parts),headers:{contentType:res.headers['content-type'],etag:res.headers.etag,lastModified:res.headers['last-modified']}}));res.on('error',reject);});req.setTimeout(30000,()=>req.destroy(Error('CSS GET timeout')));req.on('error',reject);});}
(async()=>{assert(process.argv.includes('--read-only-approved-stylesheets'));assert.equal(sha(read(BASE+'/index.html')),EXPECTED_HTML,'latest parent approved HTML CAS');const html=read(BASE+'/index.html'),hrefs=[...html.matchAll(/<link\b[^>]*\brel=["']stylesheet["'][^>]*>/g)].map(m=>m[0].match(/\bhref=["']([^"']+)["']/)[1]),manifest={},evidence=[];let cursor=0;async function worker(){while(cursor<hrefs.length){const href=hrefs[cursor++],url=new URL(href,'https://admin.51dianzi.com');assert.equal(url.origin,'https://admin.51dianzi.com');assert(url.pathname.startsWith('/assets/')&&url.pathname.endsWith('.css'));const r=await get(url),file=path.join(ROOT,'native-css',url.pathname),hash=sha(r.bytes);fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file,r.bytes);manifest[href]={path:file,sha256:hash};evidence.push({href,url:url.href,path:file,sha256:hash,bytes:r.bytes.length,method:'GET',...r.headers});console.log('CSS_READ_ONLY_SNAPSHOT '+href+' '+r.bytes.length);}}await Promise.all(Array.from({length:4},worker));assert.equal(sha(read(BASE+'/index.html')),EXPECTED_HTML,'HTML final CAS');fs.writeFileSync(ROOT+'/native-css-manifest.json',JSON.stringify(manifest,null,2)+'\n');fs.writeFileSync(ROOT+'/native-css-snapshot-evidence.json',JSON.stringify({status:'PASS',baselineHtmlSha256:EXPECTED_HTML,networkMethods:['GET'],productionWrites:0,files:evidence.sort((a,b)=>a.href.localeCompare(b.href))},null,2)+'\n');})().catch(e=>{console.error(e.stack);process.exitCode=1;});
